dtsPropsFor.ValueKnob:
/** Its name, under its face */
  label: string;
  /** Its range, default, curve, step and unit; two choices (Off, On) make it a switch */
  spec: { min: number; max: number; default: number; curve: 'linear' | 'quadratic' | 'exponential' | 'bipolar'; step: number; unit: '' | '%' | 'oct' | 'st' | 'ct' | 's' | 'Hz' | 'pan' | 'dB' | 'ratio' | 'q'; choices?: readonly string[]; atMin?: string };
  /** Where it stands: spec.default where not given */
  value?: number;
  /** Hears each turn, the value clamped to spec's range */
  onChange?: (value: number) => void;
  /** Its readout, if not its unit's (formatValue) */
  format?: (value: number) => string;
  /** Its arc's colour, and its glow while turned */
  color?: string;
  /** Its name drawn in this colour: a part's own knob called out */
  hot?: string;

dtsPropsFor.MoreMenu:
/** The items, in groups; one empty is left out, and its line. glyph: a path on a 14 px square (MENU_GLYPHS) */
  groups: readonly (readonly { label: string; glyph: string; onSelect: () => void; disabled?: boolean; danger?: boolean }[])[];
  label?: string;
  lit?: boolean;

dtsPropsFor.Popover:
/** Its element's id (the buttons' aria-controls), its heading's after it */
  id: string;
  /** The button it opens from, which places it */
  anchor: React.RefObject<HTMLElement | null>;
  /** As wide as it wants to be, in rem */
  width: number;
  /** As tall, in rem: measured from its content where not given */
  height?: number;
  chip: React.ReactNode;
  title: string;
  note?: React.ReactNode;
  /** In the header, before the cross */
  actions?: React.ReactNode;
  /** The cross's name, for a screen reader */
  closeLabel: string;
  onClose: () => void;
  /** What Escape does, if not closing it */
  onEscape?: () => void;
  /** Told once it is placed, before it is seen: its list has a size */
  onPlaced?: () => void;
  bodyClassName?: string;
  children: React.ReactNode;

dtsPropsFor.LanePicker:
/** A part's knobs a lane can move, under the part's name; name: A Filter · Cutoff */
  groups: readonly { part: string; name: string; knobs: readonly { part: string; key: string; spec: { min: number; max: number; default: number; curve: 'linear' | 'quadratic' | 'exponential' | 'bipolar'; step: number; unit: '' | '%' | 'oct' | 'st' | 'ct' | 's' | 'Hz' | 'pan' | 'dB' | 'ratio' | 'q'; choices?: readonly string[]; atMin?: string; key: string; label: string }; name: string }[] }[];
  /** The loop's lanes: one per knob already laned */
  lanes: readonly { part: string; key: string; glide: boolean; on: boolean; values: readonly number[] }[];
  onAdd: (knob: { part: string; key: string; spec: { min: number; max: number; default: number; curve: 'linear' | 'quadratic' | 'exponential' | 'bipolar'; step: number; unit: '' | '%' | 'oct' | 'st' | 'ct' | 's' | 'Hz' | 'pan' | 'dB' | 'ratio' | 'q'; choices?: readonly string[]; atMin?: string; key: string; label: string }; name: string }) => void;
  onClose: () => void;

dtsPropsFor.OrnamentPanel:
/** The note picked: its key, its ornament and whether a ghost; none before a note is tapped (the kinds disabled) */
  note?: { key: number; ornament?: ({ kind: 'grace'; interval: number; count: number; speed: 2 | 3 | 4 | 6 | 8; place: 'before' | 'on' } | { kind: 'mordent' | 'trill'; interval: number; speed: 2 | 3 | 4 | 6 | 8; restart: boolean } | { kind: 'roll'; speed: 2 | 3 | 4 | 6 | 8; shape: 'flat' | 'rise' | 'fall' } | { kind: 'arp'; chord: 'maj' | 'min' | 'sus4' | 'fifth' | 'oct' | 'maj7' | 'min7' | 'dim'; order: 'up' | 'down' | 'updown'; speed: 2 | 3 | 4 | 6 | 8; restart: boolean }); ghost?: boolean };
  /** A synth's note (its pitch moves), or a kit's pad */
  pitched: boolean;
  /** The song's, for how long a sound lasts */
  tempo: number;
  /** A key's name: a synth's note, a kit's pad */
  keyName: (key: number) => string;
  onChange: (ornament: ({ kind: 'grace'; interval: number; count: number; speed: 2 | 3 | 4 | 6 | 8; place: 'before' | 'on' } | { kind: 'mordent' | 'trill'; interval: number; speed: 2 | 3 | 4 | 6 | 8; restart: boolean } | { kind: 'roll'; speed: 2 | 3 | 4 | 6 | 8; shape: 'flat' | 'rise' | 'fall' } | { kind: 'arp'; chord: 'maj' | 'min' | 'sus4' | 'fifth' | 'oct' | 'maj7' | 'min7' | 'dim'; order: 'up' | 'down' | 'updown'; speed: 2 | 3 | 4 | 6 | 8; restart: boolean }) | undefined) => void;
  /** The note made a ghost, or a note again */
  onGhost: (ghost: boolean) => void;
  onClose: () => void;

dtsPropsFor.OutputCells:
/** A track's Mute and Solo, if it has one: a cell before the views */
  mutes?: React.ReactNode;
  /** The view its tiles show */
  shown: 'scope' | 'spectrum' | 'spectrogram' | 'stereo';
  choose: (view: 'scope' | 'spectrum' | 'spectrogram' | 'stereo') => void;

dtsPropsFor.SurfacePicker:
settings: { kind: 'keys' | 'pads' | 'xy'; root: number; scale: 'chromatic' | 'major' | 'minor' | 'dorian' | 'phrygian' | 'lydian' | 'mixolydian' | 'harmonic-minor' | 'major-pentatonic' | 'minor-pentatonic' | 'blues'; hideControls: boolean; hideSurface: boolean; wheel: boolean };
  /** The track picked is a kit: its pads */
  kit: boolean;
  /** The button it opens from, which places it */
  anchor: React.RefObject<HTMLElement | null>;
  onChange: (settings: { kind: 'keys' | 'pads' | 'xy'; root: number; scale: 'chromatic' | 'major' | 'minor' | 'dorian' | 'phrygian' | 'lydian' | 'mixolydian' | 'harmonic-minor' | 'major-pentatonic' | 'minor-pentatonic' | 'blues'; hideControls: boolean; hideSurface: boolean; wheel: boolean }) => void;
  onClose: () => void;

dtsPropsFor.SurfaceButton:
ref?: React.Ref<HTMLButtonElement>;
  settings: { kind: 'keys' | 'pads' | 'xy'; root: number; scale: 'chromatic' | 'major' | 'minor' | 'dorian' | 'phrygian' | 'lydian' | 'mixolydian' | 'harmonic-minor' | 'major-pentatonic' | 'minor-pentatonic' | 'blues'; hideControls: boolean; hideSurface: boolean; wheel: boolean };
  /** The track picked is a kit */
  kit?: boolean;
  open: boolean;
  onToggle: () => void;

dtsPropsFor.Keys:
/** Who holds which note: new Hands(player) (an export), the player { noteOn(id: number, note: number, velocity: number, slide?: number): void; noteOff(id: number): void; slide(id: number, value: number): void; bend(id: number, note: number): void }, a no-op player for a picture */
  hands: Hands;
  /** The lowest note, a white key's (MIDI: 60 is C4, MIDDLE_C) */
  lowest: number;
  octaves: number;
  label: string;
  /** Every note at full velocity; otherwise lower on a key plays louder */
  fullVelocity?: boolean;

dtsPropsFor.Pads:
/** Who holds which note: new Hands(player) (an export), the player { noteOn(id: number, note: number, velocity: number, slide?: number): void; noteOff(id: number): void; slide(id: number, value: number): void; bend(id: number, note: number): void }, a no-op player for a picture */
  hands: Hands;
  /** Pads across and rows up (padGrid(width, height), kitGrid) */
  grid: { columns: number; rows: number };
  /** A MIDI note per pad, from the bottom left (padNote) */
  notes: readonly number[];
  /** The key's root, semitones above C: its pads are marked */
  root: number;
  label: string;
  fullVelocity?: boolean;

dtsPropsFor.KitPads:
/** Who holds which note: new Hands(player) (an export), the player { noteOn(id: number, note: number, velocity: number, slide?: number): void; noteOff(id: number): void; slide(id: number, value: number): void; bend(id: number, note: number): void }, a no-op player for a picture */
  hands: Hands;
  /** Pads across and rows up (padGrid(width, height), kitGrid) */
  grid: { columns: number; rows: number };
  /** Each pad's name, from the bottom left */
  names: readonly string[];
  /** What stands small on a pad beside its name: its note, or nothing */
  marks?: readonly (string | undefined)[];
  /** The pad whose sound the editor shows */
  picked: number;
  onPick: (pad: number) => void;
  label: string;
  fullVelocity?: boolean;

dtsPropsFor.XyPad:
/** Who holds which note: new Hands(player) (an export), the player { noteOn(id: number, note: number, velocity: number, slide?: number): void; noteOff(id: number): void; slide(id: number, value: number): void; bend(id: number, note: number): void }, a no-op player for a picture */
  hands: Hands;
  /** Follows the notes still gliding: (listener) => unsubscribe; () => () => {} where nothing glides */
  watchGlides: (listener: (report: { count: number; keys: Float64Array; amounts: Float64Array; slides: Float64Array }) => void) => () => void;
  /** The lowest note across its width, MIDI */
  lowest: number;
  octaves: number;
  label: string;

dtsPropsFor.ChoiceRow:
/** The setting's name */
  label: string;
  /** A line under it saying what it does */
  hint?: string;
  /** The choices, one button each; the one whose value is value is lit */
  options: readonly { value: string | number; label: string }[];
  value: string | number;
  onChange: (value: string | number) => void;

dtsPropsFor.Dropdown:
/** The row's name, which both button and list are read by */
  labelId: string;
  /** The row's hint, when it has one */
  hintId?: string;
  /** swatch: a theme's colours, as dots before the name; glyph: a path on a 14 px square before it */
  options: readonly { value: string | number; label: string; swatch?: readonly string[]; glyph?: string }[];
  value: string | number;
  onChange: (value: string | number) => void;
  /** The editor's Sound, Seq or Mix, folded on a narrow tab rail */
  rail?: boolean;

dtsPropsFor.FadeRow:
/** The scroller's classes (its width, its padding) */
  className?: string;
  /** The row's own classes: its gap, its items' alignment */
  row?: string;
  children: React.ReactNode;
  /** Any of a div's attributes, spread on the scroller */
  id?: string;
  style?: React.CSSProperties;
  role?: string;
  'aria-label'?: string;
  'aria-labelledby'?: string;
  title?: string;
